296	/** The shell's layouts that are the app's own files, from its layouts.json: { name: "@app/<path>" }. */
297	export function shellLayoutLinks(shellDir) {
298	  let links;
299	  try { links = JSON.parse(readFileSync(join(shellDir, 'layouts.json'), 'utf8')); } catch { return {}; }
300	  if (!links || typeof links !== 'object' || Array.isArray(links)) return {};
301	  return Object.fromEntries(Object.entries(links).filter(([name, path]) => /^[a-z0-9][a-z0-9-]*$/i.test(name) && typeof path === 'string' && path.startsWith('@app/')));
302	}
303	
304	/** The shell's own layouts, by name: each layouts/<name><ext> that isn't a partial (_name). */
305	export function shellLayouts(shellDir, ext = '.eta') {
306	  let files;
307	  try { files = readdirSync(join(shellDir, 'layouts')); } catch { return []; }
308	  return files.filter(file => file.endsWith(ext) && !file.startsWith('_') && !file.startsWith('.')).map(file => file.slice(0, -ext.length)).sort();
309	}
