311	/**
312	 * The shell's layouts the app hasn't got yet (8c): designed in the shell and
313	 * not linked to an app file in layouts.json. Once the app exists, these are
314	 * the shell's Layouts group, built before the features whose pages use them.
315	 */
316	export function unbuiltLayouts(shellDir, ext = '.eta') {
317	  const links = shellLayoutLinks(shellDir);
318	  return shellLayouts(shellDir, ext).filter(name => !links[name]);
319	}
